export const BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:8080/api";


async function request(path, body) {
  const res = await fetch(`${BASE_URL}${path}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });

  let data = null;
  try {
    data = await res.json();
  } catch {
    // no body / non-JSON response
  }

  if (!res.ok || (data && data.success === false)) {
    const message = (data && data.message) || `Request failed (${res.status})`;
    throw new Error(message);
  }

  return data;
}

export const requestOtp = (phoneNumber) =>
  request("/api/auth/otp/request", { phoneNumber });

export const verifyOtp = (phoneNumber, otp) =>
  request("/api/auth/otp/verify", { phoneNumber, otp });

// TODO: confirm the real order endpoint path — assumed /api/orders below.
export const placeOrderRequest = (payload) => request("/api/orders", payload);
